/**
 * Juba Arabic (عربي جوبا) — the lingua franca of South Sudan.
 * A creole based on Sudanese Arabic, spoken as a first or second language
 * by the majority of South Sudanese. Written in Arabic script (RTL).
 *
 * Key order mirrors locales/en.ts, which is the source of truth. Every key in
 * en.ts has an entry here; `npm run i18n:check` fails the build if that stops
 * being true, so a new English string cannot ship as a bare key on this locale.
 */

